export interface InvoiceRow {
  readonly number: string;
  readonly amountCents: number;
  readonly issuedDay: string;
  readonly owner: string;
}

export interface InvoiceQuery {
  readonly page?: string;
  readonly pageSize?: string;
  readonly sort?: string;
  readonly direction?: string;
}

export interface InvoicePage {
  page: number;
  pageSize: number;
  total: number;
  pageCount: number;
  items: InvoiceRow[];
}

function positiveInteger(value: string | undefined, fallback: number): number {
  if (value === undefined || !/^\d+$/.test(value)) return fallback;
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : fallback;
}

export function selectInvoicePage(rows: readonly InvoiceRow[], query: InvoiceQuery): InvoicePage {
  const page = positiveInteger(query.page, 1);
  const pageSize = Math.min(positiveInteger(query.pageSize, 20), 100);
  const sort = query.sort === "amountCents" || query.sort === "issuedDay" ? query.sort : "number";
  const factor = query.direction === "desc" ? -1 : 1;
  const indexed = rows.map((row, index) => ({ row, index }));

  indexed.sort((left, right) => {
    const a = left.row[sort];
    const b = right.row[sort];
    const compared = typeof a === "number"
      ? a - (b as number)
      : a < b ? -1 : a > b ? 1 : 0;
    return compared === 0 ? left.index - right.index : compared * factor;
  });

  const start = (page - 1) * pageSize;
  const items = indexed.slice(start, start + pageSize).map(({ row }) => row);
  return {
    page,
    pageSize,
    total: rows.length,
    pageCount: rows.length === 0 ? 0 : Math.ceil(rows.length / pageSize),
    items,
  };
}
```

