import { selectInvoicePage, InvoiceRow } from './solution';

function equal(actual: unknown, expected: unknown, label: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function ok(condition: boolean, label: string): void {
  if (!condition) throw new Error(label);
}

const rows: readonly InvoiceRow[] = Object.freeze([
  Object.freeze({ number: 'INV-2', amountCents: 500, issuedDay: '2026-01-02', owner: 'first-500' }),
  Object.freeze({ number: 'INV-10', amountCents: -25, issuedDay: '2026-01-03', owner: 'negative' }),
  Object.freeze({ number: 'INV-1', amountCents: 500, issuedDay: '2026-01-01', owner: 'second-500' }),
  Object.freeze({ number: 'INV-3', amountCents: 0, issuedDay: '2026-01-03', owner: 'zero' }),
]);

const defaultPage = selectInvoicePage(rows, {});
ok(defaultPage.page === 1 && defaultPage.pageSize === 20, 'default pagination');
ok(defaultPage.total === 4 && defaultPage.pageCount === 1, 'default totals');
equal(defaultPage.items.map(item => item.number), ['INV-1', 'INV-10', 'INV-2', 'INV-3'], 'default JavaScript string sort');
ok(defaultPage.items.every(item => !rows.includes(item)), 'returned item objects are newly allocated');

const numeric = selectInvoicePage(rows, { sort: 'amountCents', direction: 'asc', page: '1', pageSize: '10' });
equal(numeric.items.map(item => item.owner), ['negative', 'zero', 'first-500', 'second-500'], 'numeric sort is stable');

const descendingStable = selectInvoicePage(rows, { sort: 'issuedDay', direction: 'desc', page: '1', pageSize: '10' });
equal(descendingStable.items.map(item => item.owner), ['negative', 'zero', 'first-500', 'second-500'], 'descending string sort preserves equal-key order');

const secondPage = selectInvoicePage(rows, { sort: 'amountCents', direction: 'desc', page: '2', pageSize: '2' });
equal(secondPage, {
  page: 2,
  pageSize: 2,
  total: 4,
  pageCount: 2,
  items: [
    { number: 'INV-3', amountCents: 0, issuedDay: '2026-01-03', owner: 'zero' },
    { number: 'INV-10', amountCents: -25, issuedDay: '2026-01-03', owner: 'negative' },
  ],
}, 'sort then paginate');

equal(selectInvoicePage(rows, { page: '99', pageSize: '2' }).items, [], 'page beyond end');

for (const invalid of [undefined, '', '0', '-1', '+1', '1.5', ' 2 ', '1e2', '9007199254740992']) {
  const page = selectInvoicePage(rows, { page: invalid, pageSize: invalid });
  ok(page.page === 1, `invalid page defaults: ${invalid}`);
  ok(page.pageSize === 20, `invalid page size defaults: ${invalid}`);
}

const clamped = selectInvoicePage(rows, { page: '0002', pageSize: '101', sort: 'unknown', direction: 'DESC' });
ok(clamped.page === 2 && clamped.pageSize === 100, 'digit-only values parse and page size clamps');
equal(clamped.items, [], 'clamped page may be beyond end');

const empty = selectInvoicePage([], { page: '3', pageSize: '5', sort: 'issuedDay', direction: 'desc' });
equal(empty, { page: 3, pageSize: 5, total: 0, pageCount: 0, items: [] }, 'empty input');

const resultA = selectInvoicePage(rows, { pageSize: '2' });
const resultB = selectInvoicePage(rows, { pageSize: '2' });
ok(resultA.items !== resultB.items, 'item arrays are freshly allocated');
ok(resultA.items[0] !== resultB.items[0], 'item objects are freshly allocated per call');
equal(rows, [
  { number: 'INV-2', amountCents: 500, issuedDay: '2026-01-02', owner: 'first-500' },
  { number: 'INV-10', amountCents: -25, issuedDay: '2026-01-03', owner: 'negative' },
  { number: 'INV-1', amountCents: 500, issuedDay: '2026-01-01', owner: 'second-500' },
  { number: 'INV-3', amountCents: 0, issuedDay: '2026-01-03', owner: 'zero' },
], 'input rows and order are unchanged');

